const YUGEN_STORIES={"torii":{"label":"ESPÍRITO / O LIMIAR","kanji":"鳥居","title":"Você está atravessando um limite.","paragraphs":["Um torii marca simbolicamente a passagem para um espaço sagrado nos santuários xintoístas. Muito mais que uma entrada bonita, ele convida a perceber que o lugar pede outra atitude.","O xintoísmo reúne tradições ligadas aos kami, presenças sagradas associadas à natureza, a lugares e a ancestrais. Nem todo torii é vermelho: também existem versões em madeira sem pintura e em pedra."],"detail":"Experimente: antes de entrar em um lugar especial, pare por um instante e observe o que muda na sua atenção."},"manga":{"label":"IMAGINAÇÃO / ENTRE QUADROS","kanji":"漫画","title":"O silêncio também conta histórias.","paragraphs":["Mangá é a palavra japonesa para quadrinhos. Não é um único gênero: há histórias de esporte, culinária, suspense, romance, fantasia e da vida cotidiana. Muitos volumes japoneses seguem a leitura da direita para a esquerda.","No espaço entre dois quadros, o leitor completa o movimento, o som e a passagem do tempo. Uma página pode acelerar uma batalha ou estender um olhar por vários instantes.","Shōnen, shōjo, seinen e josei são categorias editoriais associadas a públicos; elas não determinam sozinhas o tema ou a qualidade de uma obra."],"detail":"Na próxima leitura, repare no tamanho dos quadros. Como ele muda a velocidade da história?"},"ma":{"label":"COTIDIANO / ESPAÇO PARA SENTIR","kanji":"間","title":"E se o intervalo fosse parte da obra?","paragraphs":["Ma pode se referir a um intervalo ou espaço entre coisas. É uma ideia útil para perceber a arquitetura, uma pausa musical ou o tempo de um gesto.","Em vez de preencher tudo, o intervalo deixa o olhar descansar e dá significado ao que está ao redor. O vazio pode participar da composição."],"detail":"Um pequeno exercício: fique um minuto sem alternar de tarefa. Observe o que aparece quando você abre espaço."},"tea":{"label":"TRADIÇÕES / CHADŌ","kanji":"茶道","title":"Muito mais que uma xícara de chá.","paragraphs":["Chadō, o caminho do chá, envolve preparar e compartilhar matcha com atenção ao ambiente, aos utensílios, aos movimentos e às pessoas presentes. Há diferentes escolas e formas de praticá-lo.","A expressão ichi-go ichi-e é frequentemente associada a esse universo: cada encontro é singular e não se repete exatamente da mesma maneira.","A tradição não representa todos os hábitos de todos os japoneses. É uma prática cultural específica, que pode ser estudada e cultivada ao longo da vida."],"detail":"Leve a ideia para o cotidiano: prepare sua próxima bebida com calma e perceba a temperatura, o aroma e a textura."},"hanami":{"label":"TRADIÇÕES / FLORESCER","kanji":"花見","title":"Bonito porque não dura para sempre.","paragraphs":["Hanami significa contemplar flores e é especialmente associado às cerejeiras. Pessoas se reúnem em parques para observar a floração, conversar e compartilhar refeições.","O florescimento das sakuras muda conforme a região e o clima. As flores se tornaram um símbolo expressivo da passagem do tempo e da beleza efêmera."],"detail":"A contemplação começa perto: qual detalhe da sua paisagem você costuma atravessar sem perceber?"},"kintsugi":{"label":"TRADIÇÕES / REPARAR","kanji":"金継ぎ","title":"Uma nova história nas linhas da quebra.","paragraphs":["Kintsugi é uma técnica de reparo de cerâmica com laca e acabamento que pode incluir pó de ouro. As marcas da restauração se tornam visíveis, criando uma nova leitura da peça.","A imagem costuma ser usada como metáfora de reconstrução. Ainda assim, é também um ofício material, que exige conhecimento, paciência e cuidado."],"detail":"A beleza aqui nasce de olhar novamente para algo que já tem história."},"spirited":{"label":"ANIME / ENCANTAMENTO","kanji":"旅","title":"A Viagem de Chihiro","paragraphs":["Um filme de Hayao Miyazaki, do Studio Ghibli. Ao entrar em um mundo de espíritos, Chihiro precisa encontrar coragem e agir em um lugar cujas regras ainda não entende.","Vale observar os pequenos trabalhos, as refeições e os momentos de silêncio: eles tornam o fantástico estranhamente familiar."],"detail":"Para quem gosta de: fantasia, amadurecimento e mundos cheios de detalhes. Filme • 2001."},"onepiece":{"label":"MANGÁ & ANIME / AVENTURA","kanji":"海","title":"One Piece","paragraphs":["Criado por Eiichiro Oda, acompanha Monkey D. Luffy e sua tripulação em uma viagem por mares, ilhas e sonhos imensos.","Por trás da aventura e do humor, a história dá espaço a amizades, liberdade, injustiças e à importância de ter um lugar no mundo."],"detail":"Para quem gosta de: jornadas longas, universos vastos e amizades improváveis."},"silent":{"label":"MANGÁ & ANIME / VIDA & EMOÇÕES","kanji":"声","title":"A Voz do Silêncio","paragraphs":["O mangá de Yoshitoki Ōima foi adaptado para um filme dirigido por Naoko Yamada. A história aborda bullying, culpa e as dificuldades de se comunicar e reconstruir vínculos.","Olhares, gestos e o próprio desenho do som participam da narrativa. É uma obra sensível que convida a olhar para o outro com mais atenção."],"detail":"Temas sensíveis: bullying, sofrimento emocional e suicídio. Para quem busca um drama de reconciliação."},"fullmetal":{"label":"MANGÁ & ANIME / AVENTURA","kanji":"鋼","title":"Fullmetal Alchemist","paragraphs":["No mangá de Hiromu Arakawa, os irmãos Edward e Alphonse Elric buscam reparar as consequências de uma experiência alquímica.","A aventura combina mistério, ação e perguntas sobre responsabilidade, poder e o valor de uma vida. Fullmetal Alchemist: Brotherhood é uma adaptação da história do mangá."],"detail":"Para quem gosta de: fantasia, mistérios e dilemas morais. Contém violência e temas intensos."},"totoro":{"label":"ANIME / ENCANTAMENTO","kanji":"森","title":"Meu Amigo Totoro","paragraphs":["No filme de Hayao Miyazaki, duas irmãs se mudam para o campo e descobrem presenças extraordinárias na paisagem.","O encanto nasce da chuva, das árvores, do vento e de um olhar infantil que encontra mistério nas coisas simples."],"detail":"Para quem gosta de: natureza, infância e fantasia acolhedora. Filme • 1988."},"march":{"label":"MANGÁ & ANIME / VIDA & EMOÇÕES","kanji":"春","title":"March Comes in Like a Lion","paragraphs":["Criada por Chica Umino, a história acompanha Rei Kiriyama, um jovem jogador profissional de shōgi que tenta encontrar equilíbrio para além do tabuleiro.","Entre partidas e refeições compartilhadas, a obra explora solidão, afeto e a construção gradual de uma rede de apoio."],"detail":"Para quem gosta de: dramas intimistas e personagens que crescem aos poucos. Aborda depressão e bullying."}};